"""UI 管理器 - v3.0 重写版（渲染层）

修复要点（相对原 v3.0）：
- UIManager 持有 engine 引用（原 draw_all 引用不存在的 self.engine）
- font.render 第三参数传颜色（原传 True 画不出文字）
- 统一用 self.screen（原 screen 未定义 NameError）
- 提供 hit_test 与各区域 rect，供 move_handler 复用
- 用 SysFont fallback 渲染 ♥♦♣♠
"""

from __future__ import annotations

from typing import List, Optional, Tuple

import pygame

from game_engine import Card, SUIT_GLYPH

# === 布局常量 ===
SCREEN_W, SCREEN_H = 1920, 1080
CARD_W, CARD_H = 110, 160
COL_GAP = 20
COL_STRIDE = CARD_W + COL_GAP
N_COLS = 7
# 动态计算水平居中，适应不同宽高比
LEFT_MARGIN = max(16, (SCREEN_W - (N_COLS * CARD_W + (N_COLS - 1) * COL_GAP)) // 2)
TOP_Y = 28
TABLEAU_Y = 220
FAN_DOWN = 16   # 面朝下牌的纵向偏移
FAN_UP = 36     # 面朝上牌的纵向偏移

# === 颜色 ===
BG_TOP = (20, 120, 68)
BG_BOTTOM = (8, 48, 24)
CARD_FACE = (254, 252, 246)
CARD_BACK = (34, 54, 120)
CARD_BACK_TRIM = (180, 195, 238)
CARD_BACK_PATTERN = (25, 42, 94)
RED = (210, 35, 40)
BLACK = (22, 22, 28)
HIGHLIGHT = (255, 210, 50)
TEXT = (232, 228, 210)
SHADOW = (0, 0, 0, 80)
GLASS = (255, 255, 255, 18)


class UIManager:
    def __init__(self, screen: pygame.Surface, engine) -> None:
        self.screen = screen
        self.engine = engine
        pygame.font.init()
        self.font_big = pygame.font.SysFont("segoepr,arial,dejavusans,sans", 34, bold=True)
        self.font = pygame.font.SysFont("segoepr,arial,dejavusans,sans", 22, bold=True)
        self.font_small = pygame.font.SysFont("segoepr,arial,dejavusans,sans", 15)
        self.font_title = pygame.font.SysFont("segoepr,arial,dejavusans,sans", 56, bold=True)
        # 拖拽视觉状态
        self._drag_cards: List[Card] = []
        self._drag_pos: Tuple[int, int] = (0, 0)
        # 背景缓存
        self._bg = self._make_background()

    # ---------- 背板（纹理化） ----------
    def _make_background(self) -> pygame.Surface:
        surf = pygame.Surface((SCREEN_W, SCREEN_H))
        for y in range(SCREEN_H):
            t = y / SCREEN_H
            r = int(BG_TOP[0] * (1 - t) + BG_BOTTOM[0] * t)
            g = int(BG_TOP[1] * (1 - t) + BG_BOTTOM[1] * t)
            b = int(BG_TOP[2] * (1 - t) + BG_BOTTOM[2] * t)
            pygame.draw.line(surf, (r, g, b), (0, y), (SCREEN_W, y))
        # 叠加细微网格纹理，模拟桌台质感
        tile = 48
        tex = pygame.Surface((tile, tile), pygame.SRCALPHA)
        pygame.draw.rect(tex, GLASS, tex.get_rect(), 1)
        for x in range(0, SCREEN_W, tile):
            for y in range(0, SCREEN_H, tile):
                surf.blit(tex, (x, y))
        return surf

    # ---------- 布局 ----------
    def stock_rect(self) -> pygame.Rect:
        return pygame.Rect(LEFT_MARGIN, TOP_Y, CARD_W, CARD_H)

    def waste_rect(self) -> pygame.Rect:
        return pygame.Rect(LEFT_MARGIN + COL_STRIDE, TOP_Y, CARD_W, CARD_H)

    def foundation_rect(self, f: int) -> pygame.Rect:
        return pygame.Rect(LEFT_MARGIN + (4 + f) * COL_STRIDE, TOP_Y, CARD_W, CARD_H)

    def tableau_base_rect(self, col: int) -> pygame.Rect:
        return pygame.Rect(LEFT_MARGIN + col * COL_STRIDE, TABLEAU_Y, CARD_W, CARD_H)

    def tableau_card_rect(self, col: int, idx: int) -> pygame.Rect:
        stack = self.engine.tableau[col]
        y = TABLEAU_Y
        for i in range(idx):
            y += FAN_DOWN if not stack[i].face_up else FAN_UP
        return pygame.Rect(LEFT_MARGIN + col * COL_STRIDE, y, CARD_W, CARD_H)

    def hit_test(self, pos: Tuple[int, int]) -> Optional[Tuple[str, int, int]]:
        """返回 (zone, col, idx)。col 对 foundation 是 0-3，tableau 0-6，waste/stock 0。"""
        x, y = pos
        if self.stock_rect().collidepoint(x, y):
            return ("stock", 0, 0)
        if self.waste_rect().collidepoint(x, y):
            return ("waste", 0, 0)
        for f in range(4):
            if self.foundation_rect(f).collidepoint(x, y):
                return ("foundation", f, 0)
        for col in range(7):
            cx = LEFT_MARGIN + col * COL_STRIDE
            if not (cx <= x <= cx + CARD_W):
                continue
            if y < TABLEAU_Y:
                continue
            stack = self.engine.tableau[col]
            if not stack:
                if y <= TABLEAU_Y + CARD_H:
                    return ("tableau", col, -1)
                continue
            # 从顶层（idx 大）往下检测，第一个命中的即最上层可见牌
            for idx in range(len(stack) - 1, -1, -1):
                if self.tableau_card_rect(col, idx).collidepoint(x, y):
                    return ("tableau", col, idx)
            # 命中列的 x 区但落在牌缝外的尾部 → 视为顶层
            return ("tableau", col, len(stack) - 1)
        return None

    # ---------- 拖拽视觉 ----------
    def set_drag(self, cards: List[Card], pos: Tuple[int, int]) -> None:
        self._drag_cards = cards
        self._drag_pos = pos

    def clear_drag(self) -> None:
        self._drag_cards = []
        self._drag_pos = (0, 0)

    # ---------- 绘制 ----------
    def draw_all(self) -> None:
        self.screen.blit(self._bg, (0, 0))

        # foundation
        for f in range(4):
            r = self.foundation_rect(f)
            self._draw_placeholder(r, SUIT_GLYPH[list(SUIT_GLYPH)[f]])
            st = self.engine.foundation[f]
            if st:
                self._draw_face(st[-1], r.x, r.y)

        # stock
        sr = self.stock_rect()
        if self.engine.stock:
            self._draw_back(sr.x, sr.y)
        else:
            self._draw_placeholder(sr, "\u21bb")  # ↻ 可重置

        # waste
        wr = self.waste_rect()
        if self.engine.waste:
            self._draw_face(self.engine.waste[-1], wr.x, wr.y)
        else:
            self._draw_placeholder(wr, "")

        # tableau
        for col in range(7):
            stack = self.engine.tableau[col]
            if not stack:
                self._draw_placeholder(self.tableau_base_rect(col), "")
                continue
            for idx, card in enumerate(stack):
                r = self.tableau_card_rect(col, idx)
                if card.face_up:
                    self._draw_face(card, r.x, r.y)
                else:
                    self._draw_back(r.x, r.y)

        # 拖拽中的牌（跟随鼠标）
        if self._drag_cards:
            ox, oy = self._drag_pos
            for i, card in enumerate(self._drag_cards):
                self._draw_face(card, ox - CARD_W // 2, oy - CARD_H // 2 + i * FAN_UP)

        # HUD（增强：更清晰、更美观）
        hud_left = self.font.render(f"\u6b65\u6570: {self.engine.moves}", True, TEXT)
        hud_right = self.font.render("ESC 退出  R 重开  H 帮助", True, TEXT)
        self.screen.blit(hud_left, (14, SCREEN_H - 36))
        self.screen.blit(hud_right, (SCREEN_W - hud_right.get_width() - 14, SCREEN_H - 36))
        # 底部分隔线
        pygame.draw.line(self.screen, (60, 120, 80), (10, SCREEN_H - 44), (SCREEN_W - 10, SCREEN_H - 44), 1)

        if self.engine.game_over:
            self._draw_victory()

    def _draw_placeholder(self, rect: pygame.Rect, glyph: str) -> None:
        pygame.draw.rect(self.screen, (8, 48, 30), rect, border_radius=10)
        pygame.draw.rect(self.screen, (50, 100, 70), rect, 2, border_radius=10)
        # 细高光边框
        pygame.draw.line(self.screen, (70, 140, 90), (rect.x + 4, rect.y + 1),
                         (rect.right - 4, rect.y + 1), 1)
        if glyph:
            t = self.font_big.render(glyph, True, (80, 130, 100))
            self.screen.blit(t, (rect.x + (rect.w - t.get_width()) // 2,
                                 rect.y + (rect.h - t.get_height()) // 2))

    def _draw_face(self, card: Card, x: int, y: int) -> None:
        rect = pygame.Rect(x, y, CARD_W, CARD_H)
        # 阴影（带圆角）
        sh_surf = pygame.Surface((CARD_W, CARD_H), pygame.SRCALPHA)
        pygame.draw.rect(sh_surf, SHADOW, sh_surf.get_rect(), border_radius=10)
        self.screen.blit(sh_surf, (x + 3, y + 4))
        # 白色填充
        pygame.draw.rect(self.screen, CARD_FACE, rect, border_radius=10)
        col = RED if card.color == "red" else BLACK
        pygame.draw.rect(self.screen, col, rect, 3, border_radius=10)
        # 左上角
        label = f"{card.rank}{card.glyph}"
        t = self.font.render(label, True, col)
        self.screen.blit(t, (x + 8, y + 6))
        # 中央大花色
        big = self.font_big.render(card.glyph, True, col)
        self.screen.blit(big, (x + (CARD_W - big.get_width()) // 2,
                               y + (CARD_H - big.get_height()) // 2 + 8))
        # 右下角倒置
        t2 = pygame.transform.rotate(t, 180)
        self.screen.blit(t2, (x + CARD_W - t2.get_width() - 8,
                              y + CARD_H - t2.get_height() - 6))

    def _draw_selected_highlight(self, card: Card, x: int, y: int) -> None:
        """在选中牌外围绘制发光边框。"""
        rect = pygame.Rect(x, y, CARD_W, CARD_H)
        pygame.draw.rect(self.screen, HIGHLIGHT, rect, 4, border_radius=10)

    def _draw_back(self, x: int, y: int) -> None:
        rect = pygame.Rect(x, y, CARD_W, CARD_H)
        sh_surf = pygame.Surface((CARD_W, CARD_H), pygame.SRCALPHA)
        pygame.draw.rect(sh_surf, SHADOW, sh_surf.get_rect(), border_radius=10)
        self.screen.blit(sh_surf, (x + 3, y + 4))
        # 背面主体
        pygame.draw.rect(self.screen, CARD_BACK, rect, border_radius=10)
        pygame.draw.rect(self.screen, CARD_BACK_TRIM, rect, 3, border_radius=10)
        # 菱形花纹
        for ry in range(16, CARD_H - 16, 20):
            for rx in range(14, CARD_W - 14, 20):
                pygame.draw.polygon(self.screen, CARD_BACK_TRIM, [
                    (x + rx, y + ry - 6), (x + rx + 8, y + ry),
                    (x + rx, y + ry + 6), (x + rx - 8, y + ry),
                ], 1)

    def _draw_victory(self) -> None:
        overlay = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 160))
        self.screen.blit(overlay, (0, 0))
        msg = self.font_title.render("VICTORY!", True, HIGHLIGHT)
        sub = self.font.render("按 R 重新开始", True, TEXT)
        self.screen.blit(msg, ((SCREEN_W - msg.get_width()) // 2,
                               (SCREEN_H - msg.get_height()) // 2 - 20))
        self.screen.blit(sub, ((SCREEN_W - sub.get_width()) // 2,
                               (SCREEN_H - sub.get_height()) // 2 + 40))

    def show_help(self) -> None:
        lines = [
            "═ Klondike 接龙 ═",
            "",
            "【目标】",
            "  将全部 52 张牌按 A→K 顺序移至 4 个基础堆。",
            "",
            "【规则】",
            "  · Tableau（下方 7 列）：红黑交替、点数递减排列",
            "  · 空列只允许放置 K",
            "  · Foundation（上方 4 格）：同花色，A 起始到 K 结束",
            "  · Stock（左上）：点击抽 1 张到 Waste（右上）",
            "  · 最多整段移动连续的合法序列",
            "",
            "【操作】",
            "  · 左键拖拽：移动选中牌到目标位置",
            "  · 左键单击 Stock：抽牌",
            "  · 右键单击牌：自动送入 Foundation（如可放）",
            "  · R：重新开始    H：关闭本帮助    ESC：退出游戏",
        ]
        overlay = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 160))
        self.screen.blit(overlay, (0, 0))
        # 居中卡片背景
        box_w = 680
        box_h = len(lines) * 30 + 60
        box = pygame.Rect((SCREEN_W - box_w) // 2, (SCREEN_H - box_h) // 2, box_w, box_h)
        pygame.draw.rect(self.screen, (20, 20, 30, 200), box, border_radius=14)
        pygame.draw.rect(self.screen, (100, 160, 120), box, 2, border_radius=14)
        for i, ln in enumerate(lines):
            y = box.y + 30 + i * 30
            is_header = ln.startswith("═") or ln.endswith("]")
            t = self.font_big.render(ln, True, HIGHLIGHT if is_header else TEXT) if is_header else self.font.render(ln, True, TEXT)
            self.screen.blit(t, (box.x + 30, y))

    def _draw_overlay(self) -> None:
        """绘制半透明遮罩。"""
        overlay = pygame.Surface((SCREEN_W, SCREEN_H), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 160))
        self.screen.blit(overlay, (0, 0))

    def _draw_rule_box(self, title: str, lines: List[str], x_offset: int = 0) -> None:
        """在屏幕上绘制一个规则文本框，支持 x_offset 右移。"""
        box_w = 700
        box_h = len(lines) * 28 + 60
        box_x = LEFT_MARGIN + x_offset
        box_y = (SCREEN_H - box_h) // 2 - 20
        box = pygame.Rect(box_x, box_y, box_w, box_h)
        pygame.draw.rect(self.screen, (16, 16, 24, 200), box, border_radius=14)
        pygame.draw.rect(self.screen, (80, 140, 110), box, 2, border_radius=14)
        # 标题
        t = self.font_big.render(title, True, HIGHLIGHT)
        self.screen.blit(t, (box.x + 24, box.y + 18))
        # 正文
        for i, ln in enumerate(lines):
            text = self.font.render(ln, True, TEXT)
            self.screen.blit(text, (box.x + 24, box.y + 54 + i * 28))

    def show_rules(self) -> None:
        """显示完整游戏规则文档（F1 快捷键）。"""
        self._draw_overlay()
        boxes = [
            ("【游戏目标】", [
                "Klondike 接龙的唯一目标是：将 52 张牌全部移动到",
                "右上角的 4 个 Foundation 堆中。每个 Foundation",
                "必须按同一花色从 A 到 K 升序排列。",
            ]),
            ("【Tableau 规则】（下方 7 列）", [
                "• 初始发牌：第 i 列有 i+1 张牌（第 1 列 1 张，第 7 列 7 张），",
                "  仅每列最上方一张牌面朝上，其余扣下。",
                "• 移动：只能将红牌放在黑牌上，或反过来——颜色必须相反。",
                "  点数必须正好小 1（例：红 7 可放黑 8 上）。",
                "• 空列：只能放 K。K 放入空列后可以继续在其下方加牌。",
                "• 翻牌：每当一列最上方被移走后，下一张扣下牌自动翻开。",
                "• 整段移动：如果底部连续多张牌构成合法序列，可以一起拖动。",
            ]),
            ("【Foundation 规则】（上方 4 格）", [
                "• 每格一个花色。起始必须放 A。",
                "• 之后依次放 2, 3, ..., K（同花色升序）。",
                "• 只有每列最上方的牌可以直接送入 Foundation。",
                "• 右键单击牌可自动送入合适的 Foundation。",
            ]),
            ("【Stock / Waste 规则】（左上 / 右上）", [
                "• 点击 Stock 牌堆：将最上方一张牌翻开放入 Waste。",
                "• Stock 耗尽后，Waste 的所有牌会自动重新洗回 Stock。",
                "• 默认 Draw-1 模式：每次只抽 1 张（经典版）。",
                "• 可在 GameEngine.draw_from_stock() 中改为 Draw-3。",
            ]),
        ]
        for i, (label, lines) in enumerate(boxes):
            # 左侧两个 + 右侧两个
            x_off = 720 if i >= 2 else 0
            self._draw_rule_box(label, lines, x_offset=x_off)
        # 底部提示
        hint = self.font_small.render("按 F1 关闭 | 完整规则见 RULES.md 文件", True, TEXT)
        self.screen.blit(hint, ((SCREEN_W - hint.get_width()) // 2, SCREEN_H - 50))
