# ════════════════════════════════════════════════════════
# 色彩系统 — Emerald Velour
# ════════════════════════════════════════════════════════
# 背景
BG_TOP = (14, 62, 40)        # 深翠绿（顶部）
BG_BOTTOM = (3, 16, 10)      # 近黑绿（底部）
BG_CENTER_GLOW = (40, 120, 80)  # 中心柔光

# 金色系
GOLD = (212, 175, 55)
GOLD_BRIGHT = (245, 215, 110)
GOLD_DIM = (130, 100, 30)
GOLD_FAINT = (80, 62, 20)

# 卡牌正面
CARD_FACE_TOP = (255, 252, 240)     # 暖象牙（顶部高光）
CARD_FACE_BOTTOM = (228, 220, 198)  # 暖象牙（底部阴影）
