        for x in range(0, SCREEN_W, tile_s):
            for y in range(0, SCREEN_H, tile_s):
                surf.blit(noise_tile, (x, y))
        random.seed()

        # 4. 径向暗角
        self._apply_vignette(surf)

        # 5. 金色装饰边框
        self._draw_gold_frame(surf)

        return surf

