CARD_FACE_TOP = (255, 252, 240)     # 暖象牙（顶部高光）
CARD_FACE_BOTTOM = (228, 220, 198)  # 暖象牙（底部阴影）
CARD_BORDER = (190, 178, 150)       # 暖边框
CARD_INNER_HIGHLIGHT = (255, 255, 255)  # 顶部高光线

