    # ──────────────────────────────────────────────
    def _get_card_face(self, card: Card) -> pygame.Surface:
        key = f"{card.rank}{card.suit}"
        if key not in self._face_cache:
            self._face_cache[key] = self._render_card_face(card)
        return self._face_cache[key]

