        self.font_placeholder = pygame.font.SysFont(serif, 64)

        # 拖拽视觉状态
        self._drag_cards: List[Card] = []
        self._drag_pos: Tuple[int, int] = (0, 0)

        # 卡牌表面缓存
        self._face_cache: Dict[str, pygame.Surface] = {}
