# 花色
RED = (176, 34, 43)       # 深绛红
BLACK = (26, 26, 38)      # 浓墨黑

# 文本
TEXT = (235, 230, 215)    # 暖白
TEXT_GOLD = (212, 175, 55)
TEXT_MUTED = (150, 145, 125)

# 效果
SHADOW_ALPHA = 70
HIGHLIGHT = (245, 215, 110)
PLACEHOLDER_FILL = (5, 28, 16)
