            g = int(CARD_BACK_BG[1] * (1 - t * 0.4) + CARD_BACK_DARK[1] * t * 0.4)
            b = int(CARD_BACK_BG[2] * (1 - t * 0.4) + CARD_BACK_DARK[2] * t * 0.4)
            pygame.draw.line(gradient, (r, g, b), (0, y), (CARD_W, y))

